    ax.append(S.table(ps["rollout_stops"].rename(columns={"chart": "Chart, rollout presses from 2 September 2025", "stops": "Stops"})))
    rrte = ps["rollout_rate"].iloc[0]
    ax.append(f"<div class='caption'>The channel that stepped at a punch break is the one whose peak fell furthest at the stop; a stroke is part of the step when the channel's share is more than 4 sigma from its level over the strokes 300 to 21 before the stop. The rise in the total is the mean over the last 200 strokes before the stop against the run's first 500 production strokes. "
              f"The rollout presses are outside the per-stroke analysis: their monitors keep per-minute summaries, and their stops are from the fault events; {F0(rrte.stops_with_nothing_found)} stops with nothing found on {F0(rrte.strokes_in_the_per_minute_summaries)} strokes is {rrte.nothing_found_per_million_strokes:.2f} per 1,000,000 ({rrte.low:.2f} to {rrte['high']:.2f}). "
              f"The time by which a stop came before a worn punch would have made a nonconforming part is not in the record and is not reported.</div>")

    ax.append("<h3>Appendix 4. Outcomes (Section 5)</h3>")
    names = {"press_set": "Press set", "months": "Months", "year": "Year"}
    ax.append(show(o["sorting"], {**names, "sorting_events": "Sorting events", "low": "Low", "high": "High", "quantity_sorted": "Quantity sorted", "quantity_per_event_median": "Per event, median", "cost_booked": "Cost booked, $", "cost_booked_or_estimated": "Booked or estimated, $", "p_2025_against_this_year": "p, 2025 against this year"},
                   {"low": lambda v: f"{v:.1f}", "high": lambda v: f"{v:.1f}", "quantity_sorted": F0, "quantity_per_event_median": F0, "cost_booked": F0, "cost_booked_or_estimated": F0, "p_2025_against_this_year": p_value}))
    ax.append(show(o["ppm"], {**names, "complaints": "Complaints", "duplicate_entries_left_out": "Duplicate entries left out", "pieces_rejected": "Pieces rejected", "pieces_shipped": "Pieces shipped", "ppm": "PPM", "low": "Low", "high": "High", "p_2025_against_this_year": "p, 2025 against this year"},
                   {"pieces_rejected": F0, "pieces_shipped": F0, "ppm": F0, "low": F0, "high": F0, "p_2025_against_this_year": p_value}))
    ax.append(show(o["scrap_and_rework"], {**names, "scrap_booked": "Scrap booked, $", "rework_labor_booked": "Rework labor booked, $", "revenue": "Revenue, $", "scrap_and_rework_share_of_revenue": "Share of revenue"},
                   {"scrap_booked": F0, "rework_labor_booked": F0, "revenue": F0, "scrap_and_rework_share_of_revenue": lambda v: f"{v * 100:.2f}%"}))
    ax.append(show(o["scrap_and_rework"], {**names, "pieces_scrapped": "Pieces scrapped", "pieces_produced": "Pieces produced", "pieces_scrapped_share": "Share of pieces", "p_2025_against_this_year": "Score test p, 2025 against this year", "difference_low": "Difference to 2025, points, low", "difference_high": "High"},
                   {"pieces_scrapped": F0, "pieces_produced": F0, "pieces_scrapped_share": lambda v: f"{v * 100:.2f}%", "p_2025_against_this_year": p_value, "difference_low": lambda v: f"{v * 100:.2f}", "difference_high": lambda v: f"{v * 100:.2f}"}))
    ax.append(show(o["capability"], {"press_set": "Press set", "characteristics_class": "Class", "year": "Year", "characteristics": "Characteristics", "subgroups": "Subgroups", "ppk_median": "Ppk, median", "ppk_low": "Low", "ppk_high": "High", "cpk_median": "Cpk, median", "cpk_low": "Cpk low", "cpk_high": "Cpk high", "characteristics_with_ppk_under_1_33": "Ppk under 1.33"},
                   {"subgroups": F0, "ppk_median": F2, "ppk_low": F2, "ppk_high": F2, "cpk_median": F2, "cpk_low": F2, "cpk_high": F2}))
    ax.append(show(o["burr"], {"press_set": "Press set", "period_year": "Year", "burr_nonconformances_at_the_press_check": "Burr nonconformances at the press check", "burr_nonconformances_at_the_dock_audit": "At the dock audit", "burr_nonconformances_at_the_customer": "At the customer", "intervals_with_burr_gauge_subgroups": "Sharpening intervals with burr gauge subgroups",
                               "intervals_with_burr_over_the_limit": "With burr over the limit", "share_over_the_limit": "Share", "low": "Low", "high": "High"}, {"share_over_the_limit": P0, "low": P0, "high": P0}))
    ax.append(show(o["signals"], {"press_set": "Press set", "presses": "Presses", "period_year": "Year", "variable_subgroups": "Subgroups", "alarm_signals_per_100_subgroups": "Alarm signals per 100", "rule_1_per_100_subgroups": "Rule 1 per 100", "acknowledgement_or_adjustment_share": "With an acknowledgement or adjustment", "adjustment_share": "With an adjustment recorded"},
                   {"variable_subgroups": F0, "alarm_signals_per_100_subgroups": lambda v: f"{v:.1f}", "rule_1_per_100_subgroups": lambda v: f"{v:.1f}", "acknowledgement_or_adjustment_share": P0, "adjustment_share": P0}))
    ax.append(show(rm, {"month_start": "Month, 2025", "subgroups": "Subgroups on formed characteristics, pilot presses", "rule_1_alarms": "Rule 1 alarms", "rule_1_per_100_subgroups": "Per 100 subgroups"}, {"month_start": lambda v: str(v)[:7], "subgroups": F0, "rule_1_alarms": F0, "rule_1_per_100_subgroups": lambda v: f"{v:.1f}"}))
    cl = o["cost_lines"].copy(); cl.columns = [str(c) for c in cl.columns]
    ax.append(show(cl, {"press_set": "Press set", "category": "Quality cost line as booked", "2023": "2023, $", "2024": "2024, $", "2025": "2025, $"}, {"2023": F0, "2024": F0, "2025": F0}))
    cp = o["cost_lines_plant_level"].copy(); cp.columns = [str(c) for c in cp.columns]
    ax.append(show(cp, {"months": "Months", "category": "Booked at plant level", "2023": "2023, $", "2024": "2024, $", "2025": "2025, $"}, {"2023": F0, "2024": F0, "2025": F0}))
    ax.append(figure(fr["years_to_2025"], "The left panel counts sorting events on all presses by year and by the basis of the sorting; the right panel gives their cost as booked, with the estimate for sorting booked to the run. Totals are above the columns. Sorting events back to the check before carry the largest share of the cost in every year, and the sorting service carries most of 2025's."))
    ax.append(figure(fr["exposure_to_2025"], "Each point is one sorting event found at the press in 2023 to 2025: the parts made since the check before the finding, estimated at the press's realised rate, against the quantity the shop sorted, both on log scales. Points on the line are sorting events covering everything made since the check; points below it are bounded by a fault in the die-protection log."))
    ax.append(figure(fr["rejected_to_2025"], "Rejected share of the quantity sorted by the basis of the sorting, 2023 to 2025. Shares are on pieces pooled over events."))
    ax.append(figure(fo["complaints"], "Each bar is the complaints received in a month on the pilot presses' parts, 2023 to 2025, with the dates of the redesign and of per-stroke monitoring marked."))
    ax.append(figure(fo["costs"], "Each group is one category of quality cost booked to the pilot presses for March to December of the three years, on a log scale. Premium freight and customer charge-backs of 2024 stand with the complaints of that year; rework labor is as booked in each year."))
    ax.append("<div class='caption'>The score test on pieces rejects on the comparison presses as well as on the pilot presses: pieces scrapped on one run are not independent, so the test does not carry the finding and the body gives the size of the change. "
              "A complaint entered a second time for the same customer, part, run, quantity and defect code is a duplicate entry; the first received is kept. Sorting events are counted on the date the sorting started, complaints on the date received, shipments on the ship date, scrap and rework on the accounting month, and revenue on runs ended in the period at the part's price for the year. "
              "A complaint and a shipment belong to the press of their run. The sorting estimate beside the booked cost is from run hours above standard where sorting was not booked to the sorting labor code. Inspection labor, calibration, and gauge and fixture repair are booked at plant level and are not traced to a press.</div>")

    toc = [("findings", "Findings"), ("redesign", "The redesign"), ("followed", "After the redesign"), ("monitoring", "Per-stroke monitoring"), ("outcomes", "Outcomes"), ("residuals", "Residuals"), ("actions", "Actions"), ("appendix", "Appendix")]
    meta = ("Progressive-die metal stamper, about 110 employees, eleven presses, one plant; IATF 16949 certified. The record from 1 January 2023 to 31 December 2025: the redesign on PR-03, PR-06 and PR-09 (the pilot presses) from 3 February 2025, per-stroke monitoring there from 5 May 2025, and the other eight presses from 2 September 2025; "
            "SPC software, press monitor historian, ERP, QMS, die maintenance log, calibration system, accounting and gauge study worksheets. Dimensions in millimetres, tonnage in kN, costs in US dollars.<br>PPAP elements 7, 8 and 11; IATF 16949 9.1.1.1.")
    html = S.shell("SPC Redesign and Results", "Report", meta, "\n".join(body + ax), toc)
    out = S.DOCS / "reports"; out.mkdir(parents=True, exist_ok=True)
    (out / "spc_redesign_and_results.html").write_text(html, encoding="utf8", newline="\n")
    return html, pd.DataFrame(list(TRACE), columns=["section", "value_as_printed", "read_from"]), n_body, FIGURE[0]


